lemma Metric.tendsto_nhdsWithin_of_eqOn {f g : ℝ → I} {s : Set ℝ} {x : ℝ}
    {p : I} (h : Set.EqOn f g s) (hf : Filter.Tendsto f (nhdsWithin x s) (nhds p)) :
    Filter.Tendsto g (nhdsWithin x s) (nhds p)

lemma dist_fun_compactSupport_continuousOn_dist_dist {x : ℕ → X} {y : X} {p : ℕ → I} {q : I}
    (hd : StrictAnti (fun n ↦ dist (x n) y)) :
    ContinuousOn (dist_fun_compactSupport x y p q) (Set.Icc (dist (x 0) y) (dist (x 0) y + 1))

lemma ite_interpolate_uniformContinuous (a b : ℝ) (p q : I) (hab : a < b) :
    UniformContinuous (fun x ↦ if x ≤ a then p else
      if a ≤ x ∧ x ≤ b then interpolate a b p q x else q)

private lemma choice (hd : ¬ DiscreteUniformity X) (hX : ∀ x, ¬ AccPt x (⊤ : Filter X)) :
    ∀ (ε : ℝ), ε > 0 → ∀ s t : Set X, s.Finite → t.Finite →
    ∃ a : X × X, a.1 ≠ a.2 ∧ dist a.1 a.2 < ε ∧ a.1 ∉ s ∧ a.1 ∉ t ∧ a.2 ∉ s

theorem idpts_closed [TopologicalSpace M] (h : ∀ a : M, ∀ x : ℕ → M, 
    (Antitone x → Filter.Tendsto (fun n => (x n) * (x n)) Filter.atTop (nhds a) → a * a = a)) :
    IsClosed {a : M | a * a = a}

private lemma aux_mono_of_tendsto {x : ℕ → M} {p : M}
    (hx : Filter.Tendsto x Filter.atTop (nhds p)) :
    Monotone (fun n ↦ sInf (x '' Set.Ici n))

private lemma aux_le_of_tendsto {x : ℕ → M} {p : M} (hx : Filter.Tendsto x Filter.atTop (nhds p))
    (n : ℕ) :
    sInf (x '' Set.Ici n) ≤ x n

private lemma aux_tendsto_sInf_of_tendsto {x : ℕ → M} {p : M}
    (hx : Filter.Tendsto x Filter.atTop (nhds p)) :
    Filter.Tendsto (fun n ↦ sInf (x '' Set.Ici n)) Filter.atTop (nhds p)

private lemma aux_anti_of_tendsto {x : ℕ → M} {p : M}
    (hx : Filter.Tendsto x Filter.atTop (nhds p)) :
    Antitone (fun n ↦ sSup (x '' Set.Ici n))

private lemma aux_ge_of_tendsto {x : ℕ → M} {p : M} (hx : Filter.Tendsto x Filter.atTop (nhds p))
    (n : ℕ) :
    x n ≤ sSup (x '' Set.Ici n)

private lemma aux_tendsto_sSup_of_tendsto {x : ℕ → M} {p : M}
    (hx : Filter.Tendsto x Filter.atTop (nhds p)) :
    Filter.Tendsto (fun n ↦ sSup (x '' Set.Ici n)) Filter.atTop (nhds p)

lemma exists_open_containing_seq_with_compact_closure {x : ℕ → X} {y : X}
    (h : Filter.Tendsto x Filter.atTop (nhds y)) :
    ∃ U, y ∈ U ∧ Set.range x ⊆ U ∧ IsOpen U ∧ IsCompact (closure U)
